def answer(public_spec, observations, memory):
    # Compare the two paid signal-meter records for crystal 5.
    vals = {}
    for r in observations:
        if r.get('index') in (25, 168):
            msg = r.get('observation', {}).get('lastActionMessage', '')
            import re
            m = re.search(r'signal magnitude = ([0-9.]+) units', msg)
            if m:
                vals[r['index']] = float(m.group(1))
