    dialog = obs.get('dialog_box', {})
    reactor = 105
    if not dialog.get('is_in_dialog'):
        # Open the installed crystal-5 reactor to inspect its live tuning menu.
        return {'actions':[{'action':'TALK','arg1':reactor}]}
    msg = dialog.get('dialogIn','')
    m = re.search(r'current resonance frequence is: ([0-9.]+) Hertz', msg)
    if not m:
        return {'stop':'Could not read live crystal-5 reactor frequency; no further adjustment justified.'}
    f = float(m.group(1))
    if abs(f-41.2) < 1e-8:
        return {'actions':[{'chosen_dialog_option_int':1}]}
    d = f-41.2
    if d >= 1000: opt=6
    elif d >= 100: opt=7
    elif d >= 10: opt=8
    elif d >= 1: opt=9
    else: opt=5
    return {'actions':[{'chosen_dialog_option_int':opt}]}

def answer(public_spec, observations, memory):
    import re
    indices = [196,197,198,199,200,201,202,203,204,205,206,207]
    rows = {r.get('index'): r for r in observations if r.get('index') in indices}
    freqs = []
